---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")

---@class TrackMap
---@field prefabPath string[]
---@field Map TrackMapNode[]
---@field CrowData CrowData

---@class CrowData
---@field firstAttackType number
---@field appearCD number
---@field attackCD number
---@field attackDatas table

