---@field y number

---@class TrackMapReader
local TrackMapReader = Class("TrackMapReader")


local Vector3 = CS.UnityEngine.Vector3
local Mathf = CS.UnityEngine.Mathf



---@param factory_ ParkourFactory
function TrackMapReader:__init( factory_,mapName_ )
    ---@type TrackMap
    self.trackMap = import("Game.Activity.ParkourGame.MainGame.Data."..mapName_) -- !! "Level1" 这种 lua 数据文件
    self.factory = factory_
    self.width = ParkourGameUtil.InteractionTrackWidth -- 16, 一屏幕宽度(米)
    self.trackMap.curIndex = 1 -- map[] idx
    table.sort(self.trackMap.Map, function(a,b)
        return a.x < b.x
    end)
    
    self.totalPage = Mathf.Ceil(self:GetLevelLength()/self.width) -- 关卡长度一共有 几页
    if self.totalPage == 0 then
        self.totalPage = 1
    end
    self.singleMapLoop = false
end

function TrackMapReader:ImgPaths()
    return checkTable(self.trackMap.BackImgs)
end

function TrackMapReader:MiddlePrefabs()
    return checkTable(self.trackMap.MiddlePrefabs)
end
---@return CrowData
function TrackMapReader:CrowData()
    return checkTable(self.trackMap.CrowData)
end

-- 本关卡的长度
function TrackMapReader:GetLevelLength()
    return self.trackMap.Map[#self.trackMap.Map].x
end

function TrackMapReader:Reset()
    self.trackMap.curIndex = 1
end



---读取数据,为这个轨道片段生成交互物品
---@param trackSegment_ InteractionTrackSegment
function TrackMapReader:GenerateSegmentItems(trackSegment_)
    if self.singleMapLoop then
        self:GenerateSegmentItemsLoop(trackSegment_)
        return
    end

    local segmentIdx = trackSegment_.segmentIndex

    -- trackSegment pos.x 位于 segment 的正中间:
    local startPos = Mathf.Max(segmentIdx-1,0) * self.width - self.width/2
    local endPos = startPos + self.width
    
    while self.trackMap.curIndex <= #self.trackMap.Map do
        local node = self.trackMap.Map[self.trackMap.curIndex]
        if node.x < startPos then
            self.trackMap.curIndex = self.trackMap.curIndex + 1
        elseif node.x >= endPos then
            break
        else
            local localX = node.x - startPos - self.width/2
            local localY = node.y
            self.factory:GenerateTrackItem(self.trackMap.prefabPath[node.path],function(trackItem)
                trackSegment_:AddItem(trackItem, localX, localY)
            end)
            self.trackMap.curIndex = self.trackMap.curIndex + 1
        end
    end
end



-- 在单个 trackMap 内循环:  目前用户 选关 界面中;
function TrackMapReader:GenerateSegmentItemsLoop(trackSegment_)

    -- [1.self.totalPage] 之间循环
    local segmentIdx = trackSegment_.segmentIndex % self.totalPage
    if segmentIdx == 0 then
        segmentIdx = self.totalPage
    end

    local startPos = Mathf.Max(segmentIdx-1,0) * self.width - self.width/2
    local endPos = startPos + self.width

    local curIndex = 1
    
    while curIndex <= #self.trackMap.Map do
        local node = self.trackMap.Map[curIndex]
        if node.x < startPos then
            curIndex = curIndex + 1
        elseif node.x >= endPos then
            break
        else
            local localX = node.x - startPos - self.width/2
            local localY = node.y
            self.factory:GenerateTrackItem(self.trackMap.prefabPath[node.path],function(trackItem)
                trackSegment_:AddItem(trackItem, localX, localY)
            end)
            curIndex = curIndex + 1
        end
    end
end



return TrackMapReader

